import{_ as t,o as e,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"1962年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1962年/核心总结.md","filePath":"01_letters/1962年/核心总结.md"}'),l={name:"01_letters/1962年/核心总结.md"};function i(n,a,s,_,h,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1962年-核心总结" tabindex="-1">1962年 核心总结 <a class="header-anchor" href="#_1962年-核心总结" aria-label="Permalink to &quot;1962年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1962年道琼斯指数下跌7.6%，市场再度走弱。巴菲特合伙企业表现稳健，实现+13.9%的正收益，再次显著跑赢大盘。年末合伙企业净资产达到940万美元，逼近千万美元大关。从相对表现看，在市场下跌的年份依然保持正收益，进一步证明了巴菲特的投资策略具有穿越牛熊的稳定性。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>登普斯特农机制造公司成为本年的核心议题。在巴菲特的推动下，公司管理层发生了重大变化：哈里·博特尔（Harry Bottle）受命接管登普斯特。博特尔是一位擅长&quot;清算&quot;的专家，他的任务是改善公司资产负债表、清理冗余资产、优化运营。巴菲特在信中明确表示，登普斯特的内在价值正在通过这一系列操作得到提升，公司虽然经营仍具挑战，但财务状况已有所改善。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特深化了&quot;安全边际&quot;的概念。他指出，即便对企业内在价值有充分信心，也必须为错误预留空间。哈里·博特尔的加入体现了另一层投资智慧：识别问题资产后，关键不是等待，而是主动介入、创造价值。这一时期巴菲特的投资风格正在从纯粹的&quot;低估买入&quot;向&quot;低估+主动改善&quot;过渡。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>哈里·博特尔（Harry Bottle）的登场是本年的关键事件。这位擅长企业重组的专家日后成为巴菲特最信任的运营人才之一。巴菲特对他的评价极高，认为博特尔具备识别问题核心并果断行动的卓越能力。另一位值得关注的角色是登普斯特内部的保守派管理层，他们与巴菲特的新理念之间的张力，推动了公司的变革。</p>',9)])])}const p=t(l,[["render",i]]);export{u as __pageData,p as default};
